exercises.solutionCode:
import org.openqa.selenium.WebDriver;

public class SessionLab {
    public String openAndTitle(WebDriver driver, String url) {
        driver.get(url);
        String title = driver.getTitle();
        driver.quit();
        return title;
    }
}

